update public.challenges_catalog set program = $j${"phases":[{"name":"Base","weeks":3,"focus":"Técnica, fuerza general y tendones fuertes. Cargas cómodas, 2 o 3 repeticiones en reserva."},{"name":"Descarga","weeks":1,"deload":true,"focus":"Semana ligera: menos series y carga. Llegas con energía a la fase de potencia."},{"name":"Potencia","weeks":3,"focus":"Más carga en los básicos y saltos más explosivos. Lo que ganaste en la base se vuelve velocidad."},{"name":"Afinar y prueba","weeks":1,"deload":true,"focus":"Volumen bajo y tu prueba final: compara con la semana 1."}],"daysPerWeek":4,"sessionMinutes":45,"level":"todos","equipment":"Gimnasio, con versión para casa","adapt":true,"who":"Para quien corre de 5K a maratón o trail y quiere correr más fuerte y con menos lesiones, con fuerza acomodada alrededor de sus días de carrera.","result":"Fuerza pesada, pliometría y prevención de lesiones 2 a 4 veces por semana, sin tocar tus días de correr.","outcomes":["Fuerza de piernas y glúteo para una zancada más eficiente","Pantorrilla, sóleo y tibia fuertes","Saltos cortos para una zancada elástica","Prueba final para comparar con la semana 1"],"keyLifts":["squat","rdl"],"nutrition":{"mode":"recomp","proteinPerKg":1.6,"note":"Come para rendir: carbohidratos antes de tu deporte y proteína en cada comida."},"previewExercise":"rdl","experience":{"mode":"Modo Running","welcome":"Te damos la bienvenida a tu Temporada de Running. Tu fuerza va lejos de tu carrera larga: corres igual que siempre y llegas más fuerte cada semana.","habits":[{"key":"entreno","label":"Tu sesión de fuerza o tu carrera","kind":"entreno"},{"key":"carbo","label":"Carbohidratos antes de correr","kind":"check"},{"key":"agua","label":"Toma 8 vasos de agua","kind":"agua","target":8},{"key":"sueno","label":"Duerme 7 horas","kind":"sueno","target":7}],"tips":["Semana 1: cargas cómodas. Termina cada serie sintiendo que podías hacer 2 o 3 más; tus tendones se adaptan más lento que tus músculos.","Semana 2: nunca piernas pesadas el día antes de tu carrera larga. Si la mueves, mueve también tu fuerza.","Semana 3: el sóleo (pantorrilla con rodilla doblada) carga más que cualquier otro músculo al correr. No te saltes ese ejercicio.","Semana 4: semana ligera. Menos series para llegar con energía a la fase de potencia.","Semana 5: empieza la potencia. En los saltos, cada repetición es rápida y limpia; si se vuelven lentos, para.","Semana 6: si un día tus piernas no responden, haz la sesión con menos carga. Correr bien manda.","Semana 7: última semana fuerte. Mira cuánto subieron tus pesos desde la semana 1.","Semana 8: afina y prueba. Volumen bajo y tu prueba final para comparar."],"coachFocus":"Fuerza para corredores: cadena posterior, una pierna, pantorrilla y sóleo, pliometría y prevención de lesiones, siempre acomodada a sus días de carrera. Habla de su carrera larga y de su próximo evento.","restDay":"Corre según tu plan o camina 20 minutos y estira pantorrillas y cadera","food":["Antes de una carrera larga: carbohidratos de fácil digestión 2 a 3 horas antes.","Después de correr o entrenar: proteína y carbohidratos en la siguiente comida.","Más de 75 minutos corriendo: lleva algo para tomar o comer en el camino.","Proteína en cada comida para recuperar."]}}$j$::jsonb where slug = 'temporada-running-1' and kind = 'programa' and updated_by is null;
