update public.challenges_catalog set program = $j${"phases":[{"name":"Base","weeks":3,"focus":"Técnica, fuerza general y tendones fuertes. Cargas cómodas, 2 o 3 repeticiones en reserva."},{"name":"Descarga","weeks":1,"deload":true,"focus":"Semana ligera: menos series y carga. Llegas con energía a la fase de potencia."},{"name":"Potencia","weeks":3,"focus":"Más carga en los básicos y saltos más explosivos. Lo que ganaste en la base se vuelve velocidad."},{"name":"Afinar y prueba","weeks":1,"deload":true,"focus":"Volumen bajo y tu prueba final: compara con la semana 1."}],"daysPerWeek":4,"sessionMinutes":45,"level":"todos","equipment":"Gimnasio, con versión para casa","adapt":true,"who":"Para quien juega tenis o pádel y quiere más potencia, mejores desplazamientos y cuidar codo y hombro, sin llegar sin energía al partido.","result":"Fuerza de piernas, potencia de rotación, agilidad y salud de hombro y antebrazo, acomodadas a tus partidos.","outcomes":["Piernas que frenan y cambian de dirección","Rotación potente desde la cadera","Hombro, codo y muñeca más fuertes","Prueba final para comparar con la semana 1"],"keyLifts":["squat","ds:0417"],"nutrition":{"mode":"recomp","proteinPerKg":1.6,"note":"Come para rendir: carbohidratos antes de tu deporte y proteína en cada comida."},"previewExercise":"goblet","experience":{"mode":"Modo Raquetas","welcome":"Te damos la bienvenida a tu Temporada de Raquetas. Más potencia, mejores desplazamientos y brazo sano, con energía para tus partidos.","habits":[{"key":"entreno","label":"Tu sesión o tu partido","kind":"entreno"},{"key":"brazo","label":"5 minutos de hombro y muñeca","kind":"check"},{"key":"agua","label":"Toma 8 vasos de agua","kind":"agua","target":8},{"key":"sueno","label":"Duerme 7 horas","kind":"sueno","target":7}],"tips":["Semana 1: el golpe nace en las piernas. Fuerza de piernas primero, brazo después.","Semana 2: nunca piernas pesadas el día antes de un partido. Si cambia tu partido, cambia tu sesión.","Semana 3: el manguito rotador se entrena con poco peso y mucho control. Lento y sin dolor.","Semana 4: semana ligera. Juega más suelto y deja que el cuerpo absorba lo que entrenaste.","Semana 5: potencia de rotación: gira desde la cadera, no desde el brazo.","Semana 6: en los saltos laterales, frena firme como cuando llegas a una bola abierta.","Semana 7: última semana fuerte. Compara tus saltos laterales con la semana 1.","Semana 8: afina y prueba. Llega con energía a tus partidos."],"coachFocus":"Tenis y pádel: fuerza de piernas, potencia de rotación, agilidad lateral y salud de hombro, codo y muñeca, acomodado a sus partidos. Habla de sus partidos y torneos.","restDay":"Juega según tu plan o camina 20 minutos y haz movilidad de hombro","food":["Antes de jugar: una comida con carbohidratos 2 a 3 horas antes.","Partidos de más de 90 minutos: agua y algo de carbohidrato en los cambios de lado.","Después del partido: proteína y carbohidratos para recuperar.","Si sudas mucho, suma sal a tu comida del día."]}}$j$::jsonb where slug = 'temporada-raquetas-1' and kind = 'programa' and updated_by is null;
