update public.challenges_catalog set program = $j${"phases":[{"name":"Base","weeks":3,"focus":"Técnica, fuerza general y tendones fuertes. Cargas cómodas, 2 o 3 repeticiones en reserva."},{"name":"Descarga","weeks":1,"deload":true,"focus":"Semana ligera: menos series y carga. Llegas con energía a la fase de potencia."},{"name":"Potencia","weeks":3,"focus":"Más carga en los básicos y saltos más explosivos. Lo que ganaste en la base se vuelve velocidad."},{"name":"Afinar y prueba","weeks":1,"deload":true,"focus":"Volumen bajo y tu prueba final: compara con la semana 1."}],"daysPerWeek":4,"sessionMinutes":45,"level":"todos","equipment":"Gimnasio, con versión para casa","adapt":true,"who":"Para quien va a un box o entrena funcional y quiere más fuerza, mejor técnica y más aguante, con escalas para cada movimiento.","result":"Bloques de fuerza, técnica de olímpicos con carga ligera, acondicionamiento con escalas y gimnásticos.","outcomes":["Sentadilla, peso muerto y press más fuertes","Técnica de cargada y swing","Más rondas en el mismo tiempo","Benchmark en las semanas 1 y 8"],"keyLifts":["squat","deadlift"],"nutrition":{"mode":"recomp","proteinPerKg":1.6,"note":"Come para rendir: carbohidratos antes de tu deporte y proteína en cada comida."},"previewExercise":"goblet","experience":{"mode":"Modo Cross Training","welcome":"Te damos la bienvenida a tu Temporada de Cross Training. Fuerza, técnica y acondicionamiento con escalas: primero el movimiento, después la carga.","habits":[{"key":"entreno","label":"Tu sesión o tu clase","kind":"entreno"},{"key":"proteina","label":"Proteína en cada comida","kind":"proteina"},{"key":"agua","label":"Toma 8 vasos de agua","kind":"agua","target":8},{"key":"sueno","label":"Duerme 7 horas","kind":"sueno","target":7}],"tips":["Semana 1: anota tu benchmark. Es tu punto de partida, no un examen.","Semana 2: técnica antes que carga en la cargada y el swing. Si la forma se rompe, baja el peso.","Semana 3: elige la escala que te deja moverte bien todo el circuito. Eso es lo que más te hace avanzar.","Semana 4: semana ligera. Menos series y más movilidad.","Semana 5: empieza la potencia: series cortas y pesadas con descanso completo.","Semana 6: los gimnásticos se ganan con progresiones. Nada de forzar el rango con dolor.","Semana 7: última semana fuerte. Mira tus pesos de la semana 1.","Semana 8: repite tu benchmark y compara."],"coachFocus":"Cross Training: fuerza, técnica de olímpicos con carga ligera, acondicionamiento con escalas y progresiones gimnásticas, sin forzar con dolor. Respeta lo que la persona no puede o no quiere hacer.","restDay":"Descanso activo: 20 minutos de caminata y movilidad de cadera y hombro","food":["Proteína en cada comida para recuperar entre sesiones.","Carbohidratos alrededor de tus sesiones fuertes.","Agua durante el día, no solo en el entreno.","Si entrenas en ayunas y te mareas, come algo ligero antes."]}}$j$::jsonb where slug = 'temporada-cross-1' and kind = 'programa' and updated_by is null;
